CASE WHEN instr({{time}},char(0))=0 AND CAST(substr({{time}},12,2) AS INTEGER)<=23 AND strftime('%Y-%m-%dT%H:%M:%S',upper(substr({{time}},1,17)||CASE WHEN substr({{time}},18,2)='60' THEN '59' ELSE substr({{time}},18,2) END)||'Z')=upper(substr({{time}},1,17)||CASE WHEN substr({{time}},18,2)='60' THEN '59' ELSE substr({{time}},18,2) END) AND (CASE WHEN lower(substr({{time}},-1))='z' THEN 1 ELSE substr({{time}},-6) GLOB '[+-][0-2][0-9]:[0-5][0-9]' AND CAST(substr({{time}},-5,2) AS INTEGER)<=23 END) AND (CASE WHEN substr({{time}},20,1)='.' THEN length(substr({{time}},21,length({{time}})-20-(CASE WHEN lower(substr({{time}},-1))='z' THEN 1 ELSE 6 END)))>0 AND substr({{time}},21,length({{time}})-20-(CASE WHEN lower(substr({{time}},-1))='z' THEN 1 ELSE 6 END)) NOT GLOB '*[^0-9]*' ELSE length({{time}})=19+(CASE WHEN lower(substr({{time}},-1))='z' THEN 1 ELSE 6 END) END) THEN (CASE WHEN substr({{time}},20,1)='.' THEN CAST(substr((substr({{time}},21,length({{time}})-20-(CASE WHEN lower(substr({{time}},-1))='z' THEN 1 ELSE 6 END)))||'000000000',1,9) AS INTEGER) ELSE 0 END)+(CASE WHEN substr({{time}},18,2)='60' THEN 1000000000 ELSE 0 END) ELSE 0 END
